require __DIR__.'/inc/core.php';auth();$pdo=db();$uid=(int)$_SESSION['uid'];$err='';$ready=true;
try{$pdo->query('SELECT deleted_at FROM ek_notifications LIMIT 0');}catch(Throwable $e){$ready=false;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify();
 if($ready){
  $action=(string)($_POST['action']??'');
  if($action==='read'){$id=max(0,(int)($_POST['id']??0));$s=$pdo->prepare('UPDATE ek_notifications SET read_at=NOW() WHERE id=? AND recipient_id=? AND read_at IS NULL');$s->execute([$id,$uid]);}
  elseif($action==='delete'){$id=max(0,(int)($_POST['id']??0));$s=$pdo->prepare('UPDATE ek_notifications SET deleted_at=NOW() WHERE id=? AND recipient_id=? AND deleted_at IS NULL');$s->execute([$id,$uid]);}
  elseif($action==='delete_read'){$s=$pdo->prepare('UPDATE ek_notifications SET deleted_at=NOW() WHERE recipient_id=? AND read_at IS NOT NULL AND deleted_at IS NULL');$s->execute([$uid]);}
  elseif($action==='delete_all'){$s=$pdo->prepare('UPDATE ek_notifications SET deleted_at=NOW() WHERE recipient_id=? AND deleted_at IS NULL');$s->execute([$uid]);}
  elseif($action==='all'){$s=$pdo->prepare('UPDATE ek_notifications SET read_at=NOW() WHERE recipient_id=? AND read_at IS NULL AND deleted_at IS NULL');$s->execute([$uid]);}
 }
 redirect('notifications.php');
}
$filter=(string)($_GET['filter']??'all');if(!in_array($filter,['all','unread','approved','contracts'],true))$filter='all';$rows=[];$unread=0;
if($ready){
 $s=$pdo->prepare('SELECT COUNT(*) FROM ek_notifications WHERE recipient_id=? AND read_at IS NULL AND deleted_at IS NULL');$s->execute([$uid]);$unread=(int)$s->fetchColumn();
 $sql='SELECT n.id,n.quote_id,n.event_type,n.title,n.body,n.created_at,n.read_at,q.quote_no,c.name AS customer_name FROM ek_notifications n LEFT JOIN quotes q ON q.id=n.quote_id LEFT JOIN customers c ON c.id=q.customer_id WHERE n.recipient_id=? AND n.deleted_at IS NULL'.($filter==='unread'?' AND n.read_at IS NULL':($filter==='approved'?" AND n.event_type IN ('quote_accepted','contract_signed')":($filter==='contracts'?" AND n.event_type='contract_signed'":''))).' ORDER BY n.id DESC LIMIT 100';
 $s=$pdo->prepare($sql);$s->execute([$uid]);$rows=$s->fetchAll();
}
