<div class="ekn-list"><?php foreach($rows as $r):?><article class="ekn-item <?=empty($r['read_at'])?'new':''?> <?=$r['event_type']==='quote_rejected'?'rejected':''?>"><div class="ekn-icon"><?=in_array($r['event_type'],['quote_accepted','contract_signed'],true)?'✓':'!'?></div><div class="ekn-main"><h3><?=h($r['title'])?></h3><p><?=h($r['body'])?></p><span class="ekn-date"><?=h(date('d.m.Y H:i',strtotime($r['created_at'])))?> · <?=empty($r['read_at'])?'Yeni bildirim':'Okundu'?></span></div><div class="ekn-actions"><?php if($r['quote_id']):?><a href="<?=($r['event_type']==='contract_signed'?'v11-documents.php':'view.php')?>?id=<?=(int)$r['quote_id']?>"><?=($r['event_type']==='contract_signed'?'Sözleşmeyi Aç':'Teklifi Aç')?></a><?php endif;?><?php if(empty($r['read_at'])):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="read"><button type="submit">Okundu</button></form><?php endif;?><form method="post" onsubmit="return confirm('Bu bildirimi silmek istiyor musunuz?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="action" value="delete"><button type="submit">Sil</button></form></div></article><?php endforeach;?><?php if(!$rows):?><div class="ekn-empty"><strong>Henüz bildirim bulunmuyor</strong><p>Müşteri teklif bağlantısından onay veya ret verdiğinde burada görünecek.</p></div><?php endif;?></div><?php endif;?></section><?php bottom(); ?>
